import numpy as np
from scirel.fusion import scale_nbi_velocity_for_energy_component
ray = np.array([1.0, 0.0, 0.0])
full = scale_nbi_velocity_for_energy_component(ray, 2.0e8, 1)
third = scale_nbi_velocity_for_energy_component(ray, 2.0e8, 3)
np.testing.assert_array_equal(full, ray * 2.0e8)
assert abs(np.linalg.norm(third) - 2.0e8 / np.sqrt(3.0)) < 3.0
try:
    scale_nbi_velocity_for_energy_component(ray, float('nan'), 1)
except ValueError:
    pass
else:
    raise AssertionError('a NaN speed must be rejected')
tilted = np.array([1.0 + 1e-12, 0.0, 0.0])
try:
    scale_nbi_velocity_for_energy_component(tilted, np.finfo(float).max, 1)
except ValueError:
    pass
else:
    raise AssertionError('a norm-overflowing finite ray must be rejected')
